sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
	//order updated as part of MSSCUSTODY3120
	//Storing current values of assigned to and assignment group
    var currentAssignedTo = g_form.getValue('assigned_to');
    var assignGroupId = g_form.getValue('assignment_group');

	//condition to validate whether assigned to is empty
//	if (currentAssignedTo == '') {
        var grAjaxUser = new GlideAjax('HSBCTradeTaskUtils'); //calling script include here
        grAjaxUser.addParam('sysparm_name', 'LoggedUserAssigned');
        grAjaxUser.addParam('sysparm_grpID', assignGroupId);
        grAjaxUser.getXMLAnswer(AutopopulateAssignTo);
  //  }
    function AutopopulateAssignTo(response) {
        var currentUserId = response;
		//if(currentAssignedTo == g_form.getValue(trade_case_id.current_maker_assignee))
		//	alert('Checker cannot be the same user who actioned the maker task');
        //else	
			g_form.setValue('assigned_to', currentUserId);
    }
}
